using System;using System.IO;using System.Reflection;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;using DragonCompanion;
class Comparison{
 static Brush B(string c){return new SolidColorBrush((Color)ColorConverter.ConvertFromString(c));}
 static TextBlock Text(string text,double size,string color){return new TextBlock{Text=text,FontSize=size,FontFamily=new FontFamily("Microsoft YaHei UI"),Foreground=B(color),TextAlignment=TextAlignment.Center,Margin=new Thickness(2,5,2,2)};}
 [STAThread]static void Main(string[] args){string root=Path.GetFullPath(args[0]);string output=Path.Combine(root,"out","renders");Directory.CreateDirectory(output);foreach(bool dark in new[]{false,true}){var outer=new Grid{Width=1920,Height=600,Background=B(dark?"#151222":"#ECE8F4")};outer.RowDefinitions.Add(new RowDefinition{Height=new GridLength(70)});outer.RowDefinitions.Add(new RowDefinition{Height=new GridLength(1,GridUnitType.Star)});var heading=Text("六档龙娘 · 形态与特效进阶     /     Max 保持原样 · Ultra 星冠巨翼重绘",25,dark?"#F5E9FF":"#4D3268");heading.VerticalAlignment=VerticalAlignment.Center;outer.Children.Add(heading);var cards=new Grid{Margin=new Thickness(8,0,8,12)};Grid.SetRow(cards,1);outer.Children.Add(cards);string[] forms={"chibi","medium","full","xhigh","max","ultra"};string[] labels={"低 · Q 版","中等 · 持书","高 · 全身","极高 · 施法","Max · 龙后","Ultra · 星冠巨翼"};string[] notes={"萌态 / 呼吸 / 轻星光","知性 / 发丝 / 水晶书","优雅 / 裙摆 / 小翼","施法 / 展翼 / 能量流","王冠 / 礼装 / 浮空","晶冠 / 星纹巨翼 / 星轨"};for(int i=0;i<6;i++){cards.ColumnDefinitions.Add(new ColumnDefinition());var content=new Grid();content.RowDefinitions.Add(new RowDefinition{Height=new GridLength(1,GridUnitType.Star)});content.RowDefinitions.Add(new RowDefinition{Height=new GridLength(42)});content.RowDefinitions.Add(new RowDefinition{Height=new GridLength(38)});var border=new Border{CornerRadius=new CornerRadius(18),Margin=new Thickness(5),Background=B(dark?"#211A33":"#FAF8FF"),BorderBrush=B(i==5?"#A575E3":dark?"#463453":"#D8CCE6"),BorderThickness=new Thickness(i==5?2:1),Child=content};Grid.SetColumn(border,i);cards.Children.Add(border);var p=new AnimatedPortrait{MotionEnabled=false,Margin=new Thickness(4)};p.Form=forms[i];p.Source=new BitmapImage(new Uri(Path.Combine(root,"assets",forms[i]+".png")));typeof(AnimatedPortrait).GetField("switchedAt",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(p,-100.0);content.Children.Add(p);var label=Text(labels[i],21,dark?"#F2DBFF":"#613781");Grid.SetRow(label,1);content.Children.Add(label);var note=Text(notes[i],14,dark?"#BDA7CF":"#8B739E");Grid.SetRow(note,2);content.Children.Add(note);outer.Measure(new Size(1920,600));outer.Arrange(new Rect(0,0,1920,600));outer.UpdateLayout();p.Step(1.7);}
 outer.UpdateLayout();var bitmap=new RenderTargetBitmap(1920,600,96,96,PixelFormats.Pbgra32);bitmap.Render(outer);var enc=new PngBitmapEncoder();enc.Frames.Add(BitmapFrame.Create(bitmap));using(var f=File.Create(Path.Combine(output,dark?"six-forms-dark.png":"six-forms-light.png")))enc.Save(f);}Console.WriteLine("PASS native six-form comparison rendered on light and dark backgrounds");}
}
